--
-- Table structure for table `hourly_forecast`
--

DROP TABLE IF EXISTS `hourly_forecast`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hourly_forecast` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `city` varchar(50) NOT NULL,
  `fx_time` datetime NOT NULL,
  `temp` float DEFAULT NULL,
  `humidity` float DEFAULT NULL,
  `wind_speed` float DEFAULT NULL,
  `wind_dir` varchar(20) DEFAULT NULL,
  `pop` float DEFAULT NULL,
  `text` varchar(50) DEFAULT NULL,
  `icon` varchar(10) DEFAULT NULL,
  `wind360` float DEFAULT NULL,
  `wind_scale` varchar(10) DEFAULT NULL,
  `precip` float DEFAULT NULL,
  `pressure` float DEFAULT NULL,
  `cloud` float DEFAULT NULL,
  `dew` float DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=481 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

